/* ==========================================================================
   КранРемСервис — Основной скрипт
   ========================================================================== */

/* -------------------------------------------------------------------------
   1. Плавный скролл к форме заявки (кнопка "Оставить заявку" в hero)
   ------------------------------------------------------------------------- */
function scrollToForm() {
  var applicationSection = document.getElementById("application");
  if (applicationSection) {
    applicationSection.scrollIntoView({ behavior: "smooth" });
  }
}

/* -------------------------------------------------------------------------
   2. Плавный скролл по всем якорным ссылкам (href="#...")
   ------------------------------------------------------------------------- */
document.addEventListener("DOMContentLoaded", () => {
  document.querySelectorAll('a[href^="#"]').forEach((link) => {
    link.addEventListener("click", function (event) {
      event.preventDefault();

      const targetId = this.getAttribute("href");
      const targetElement = document.querySelector(targetId);

      if (targetElement) {
        targetElement.scrollIntoView({ behavior: "smooth" });
      }
    });
  });
});

/* -------------------------------------------------------------------------
   3. Подсветка активного пункта меню при скролле
   ------------------------------------------------------------------------- */
document.addEventListener("DOMContentLoaded", () => {
  const sections = document.querySelectorAll("section[id], footer[id]");
  const navItems = document.querySelectorAll(".nav-links a.nav-item");
  const hasContact = document.getElementById("contact") !== null;

  function updateActiveNav() {
    let currentSectionId = "";
    const scrollPosition = window.scrollY + 150;

    sections.forEach((section) => {
      if (scrollPosition >= section.offsetTop) {
        currentSectionId = section.getAttribute("id");
      }
    });

    // Низ страницы считаем контактами, только если такой раздел есть на странице
    const atBottom =
      window.innerHeight + window.scrollY >= document.body.offsetHeight - 150;
    if (hasContact && atBottom) {
      currentSectionId = "contact";
    }

    navItems.forEach((item) => {
      item.classList.remove("active");
      const href = item.getAttribute("href");

      if (
        currentSectionId &&
        (href === "#" + currentSectionId ||
          href === "index.html#" + currentSectionId)
      ) {
        item.classList.add("active");
      }
    });
  }

  window.addEventListener("scroll", updateActiveNav, { passive: true });
  updateActiveNav();
});

/* -------------------------------------------------------------------------
   4. Мобильное меню (гамбургер) + выпадающее меню "Услуги"
   ------------------------------------------------------------------------- */
document.addEventListener("DOMContentLoaded", function () {
  const hamburgerBtn = document.getElementById("hamburger-btn");
  const navLinks = document.querySelector(".nav-links");

  if (hamburgerBtn && navLinks) {
    hamburgerBtn.addEventListener("click", function () {
      navLinks.classList.toggle("open");
    });

    // Закрываем меню при клике на любой пункт
    document.querySelectorAll(".nav-item, .btn-sales").forEach((item) => {
      item.addEventListener("click", function () {
        navLinks.classList.remove("open");
      });
    });
  }

  // Раскрытие выпадающего меню "Услуги" на мобильных
  document.querySelectorAll(".nav-dropdown-toggle").forEach(function (toggle) {
    toggle.addEventListener("click", function (e) {
      if (window.innerWidth <= 1024) {
        e.preventDefault();
        const parent = this.closest(".nav-dropdown");
        parent.classList.toggle("open");
      }
    });
  });
});

/* -------------------------------------------------------------------------
   5. Отправка формы заявки через Web3Forms
   ------------------------------------------------------------------------- */
document.addEventListener("DOMContentLoaded", function () {
  const form = document.getElementById("requestForm");
  if (!form) return;

  form.addEventListener("submit", async function (event) {
    event.preventDefault();

    const submitBtn = document.getElementById("submitBtn");
    const successMessage = document.getElementById("successMessage");

    if (!submitBtn || !successMessage) return;

    submitBtn.disabled = true;
    submitBtn.innerText = "Отправка...";

    const formData = new FormData(form);
    formData.append("access_key", "78301c8e-5c71-4ad0-81cf-b4e77aaec499");

    try {
      const response = await fetch("https://api.web3forms.com/submit", {
        method: "POST",
        body: formData,
      });

      const data = await response.json();

      if (response.ok) {
        form.style.display = "none";
        successMessage.style.display = "block";
      } else {
        alert("Ошибка: " + data.message);
        submitBtn.disabled = false;
        submitBtn.innerText = "Отправить заявку";
      }
    } catch (error) {
      alert("Ошибка сети. Проверьте подключение.");
      submitBtn.disabled = false;
      submitBtn.innerText = "Отправить заявку";
    }
  });
});

/* -------------------------------------------------------------------------
   6. Анимация появления блоков (fade-up) при скролле
   ------------------------------------------------------------------------- */
document.addEventListener("DOMContentLoaded", () => {
  const observer = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("visible");
          observer.unobserve(entry.target);
        }
      });
    },
    { threshold: 0.1 },
  );

  document
    .querySelectorAll(
      ".service-card, .company-description .content-block, .form-box, .footer-text-block",
    )
    .forEach((element) => {
      element.classList.add("fade-up");
      observer.observe(element);
    });
});

/* -------------------------------------------------------------------------
   7. Слайдер фотографий в hero-блоке
   ------------------------------------------------------------------------- */
document.addEventListener("DOMContentLoaded", () => {
  const sliderWrapper = document.querySelector(".photo-slider-wrapper");
  if (!sliderWrapper) return;

  const slides = document
    .getElementById("photoSlider")
    .querySelectorAll(".slide");
  const prevBtn = sliderWrapper.querySelector(".prev-btn");
  const nextBtn = sliderWrapper.querySelector(".next-btn");

  let currentIndex = 0;
  let autoSlideInterval;

  function showSlide(index) {
    slides.forEach((slide) => slide.classList.remove("active"));
    slides[index].classList.add("active");
  }

  function nextSlide() {
    currentIndex = (currentIndex + 1) % slides.length;
    showSlide(currentIndex);
  }

  function prevSlide() {
    currentIndex = (currentIndex - 1 + slides.length) % slides.length;
    showSlide(currentIndex);
  }

  function startAutoSlide() {
    autoSlideInterval = setInterval(nextSlide, 4000);
  }

  sliderWrapper.addEventListener("mouseenter", () => {
    clearInterval(autoSlideInterval);
  });

  sliderWrapper.addEventListener("mouseleave", () => {
    clearInterval(autoSlideInterval);
    startAutoSlide();
  });

  nextBtn.addEventListener("click", () => {
    nextSlide();
    clearInterval(autoSlideInterval);
    startAutoSlide();
  });

  prevBtn.addEventListener("click", () => {
    prevSlide();
    clearInterval(autoSlideInterval);
    startAutoSlide();
  });

  startAutoSlide();
});

/* -------------------------------------------------------------------------
   8. Скрытие/показ центральной кнопки при открытии мобильного меню
   ------------------------------------------------------------------------- */
document.addEventListener("DOMContentLoaded", function () {
  const hamburgerBtn = document.getElementById("hamburger-btn");
  const navLinks = document.querySelector(".nav-links");
  const centerBtn = document.getElementById("center-btn");

  if (hamburgerBtn && navLinks && centerBtn) {
    centerBtn.style.display = "inline-block";

    hamburgerBtn.addEventListener("click", function () {
      if (navLinks.classList.contains("open")) {
        centerBtn.style.display = "none";
      } else {
        centerBtn.style.display = "inline-block";
      }
    });

    document.querySelectorAll(".nav-item, .btn-sales").forEach(function (item) {
      item.addEventListener("click", function () {
        navLinks.classList.remove("open");
        centerBtn.style.display = "inline-block";
      });
    });
  }
});

/* -------------------------------------------------------------------------
   9. Плавающие кнопки при скролле (Sticky Actions)
   ------------------------------------------------------------------------- */
document.addEventListener("DOMContentLoaded", () => {
  const placeholder = document.getElementById("actions-placeholder");
  const buttons = document.getElementById("floating-actions");

  if (!placeholder || !buttons) return;

  window.addEventListener("scroll", () => {
    // Получаем позицию нашей невидимой обертки относительно экрана
    const rect = placeholder.getBoundingClientRect();

    // Высота вашей шапки примерно 70px.
    // Если обертка уходит под шапку (rect.top <= 70), мы "отрываем" кнопки
    if (rect.top <= 70) {
      buttons.classList.add("floating");
    } else {
      // Иначе возвращаем их на место в центр
      buttons.classList.remove("floating");
    }
  });
});

/* -------------------------------------------------------------------------
   10. видео запускается
   ------------------------------------------------------------------------- */

document.addEventListener("DOMContentLoaded", function () {
  const video = document.querySelector(".tooltip-video-wrapper video");
  const tooltipBox = document.querySelector(".company-tooltip-box");

  if (video && tooltipBox) {
    // Когда видео запускается, добавляем класс, который не даст окну закрыться
    video.addEventListener("play", function () {
      tooltipBox.classList.add("force-visible");
    });

    // Когда ставим на паузу или видео кончается — снимаем блокировку
    video.addEventListener("pause", function () {
      tooltipBox.classList.remove("force-visible");
    });
    video.addEventListener("ended", function () {
      tooltipBox.classList.remove("force-visible");
    });

    // Железобетонная защита для полноэкранного режима
    video.addEventListener("fullscreenchange", function () {
      if (document.fullscreenElement) {
        tooltipBox.classList.add("force-visible");
      } else if (video.paused) {
        tooltipBox.classList.remove("force-visible");
      }
    });
  }
});

/* -------------------------------------------------------------------------
   11. интерфейс дружелюбнее
   ------------------------------------------------------------------------- */
document.addEventListener("DOMContentLoaded", function () {
  const video = document.querySelector(".tooltip-video-wrapper video");
  const tooltipBox = document.querySelector(".company-tooltip-box");

  if (video && tooltipBox) {
    // Удерживаем окно при воспроизведении
    video.addEventListener("play", function () {
      tooltipBox.classList.add("force-visible");
    });

    // Снимаем удержание при паузе
    video.addEventListener("pause", function () {
      tooltipBox.classList.remove("force-visible");
    });

    // Когда видео заканчивается
    video.addEventListener("ended", function () {
      tooltipBox.classList.remove("force-visible");

      // Автоматически выходим из полноэкранного режима
      if (document.fullscreenElement) {
        document.exitFullscreen().catch((err) => console.log(err));
      } else if (document.webkitFullscreenElement) {
        // Для браузеров на движке WebKit (Safari)
        document.webkitExitFullscreen();
      }
    });

    // Защита окна в полноэкранном режиме
    video.addEventListener("fullscreenchange", function () {
      if (document.fullscreenElement) {
        tooltipBox.classList.add("force-visible");
      } else if (video.paused) {
        tooltipBox.classList.remove("force-visible");
      }
    });
  }
});
